class Solution:
    def maxDistance(self, s: str, k: int) -> int:
        counts = {"N": 0, "S": 0, "E": 0, "W": 0}
        ans = 0

        for i, ch in enumerate(s, 1):
            counts[ch] += 1

            # For each target quadrant, the "bad" moves are the two opposite directions.
            bad_options = (
                counts["S"] + counts["W"],  # target NE
                counts["S"] + counts["E"],  # target NW
                counts["N"] + counts["W"],  # target SE
                counts["N"] + counts["E"],  # target SW
            )

            for bad in bad_options:
                ans = max(ans, i - 2 * max(0, bad - k))

        return ans
